    func testChoiceAndFallbackAreCompleteNativeTopicPreview() throws {
        let value = try ModInstallationTopicGraph(json: graph)
        XCTAssertEqual(value.nodes.map(\.id), ["intro", "middle", "end", "alternate"])
        XCTAssertEqual(value.nodes[1].fallbackChoiceId, "left")
        XCTAssertEqual(value.nodes[1].choices?.map(\.id), ["left", "right"])
        XCTAssertEqual(value.fallbacks.first?.toNodeKey, "end")
        XCTAssertTrue(value.edges.contains { $0.id == "middle.right" && $0.toNodeKey == "alternate" && $0.trigger.outcomeCode == "right" })
    }
    func testAlteredFallbackOrDroppedNodeCannotBecomePartialPreview() {
        XCTAssertThrowsError(try ModInstallationTopicGraph(json: graph.replacingOccurrences(of: "\"fallbackChoiceId\":\"left\"", with: "\"fallbackChoiceId\":\"right\"")))
        XCTAssertThrowsError(try ModInstallationTopicGraph(json: graph.replacingOccurrences(of: "\"sourceNodeId\":\"alternate\"", with: "\"sourceNodeId\":\"missing\"")))
        XCTAssertThrowsError(try ModInstallationTopicGraph(json: graph.replacingOccurrences(of: "\"adapter\":", with: "\"script\":\"forbidden\",\"adapter\":")))
    }
