        let hash = String(repeating: "a", count: 64)
        let receipt = ModInstallationReceipt(schema: "mod-installation-receipt-v1", requestId: "00000000-0000-0000-0000-000000000001",
            licenseId: "synthetic-license", moduleId: "synthetic-module", releaseId: "synthetic-release", contentHash: hash, termsHash: hash,
            state: .installed, merchantId: 10, anchorPoiId: 20, region: "synthetic-region", bindingHash: hash, draftId: 30, editKind: "TOPIC",
            createdAt: "2026-10-21T00:00:00.000000Z", errorCode: nil, published: false, executable: false,
            requiredGates: ["MERCHANT_FACT_CONFIRMATION", "THEME_CONTENT_REVIEW", "W02_PUBLISH"], bindings: [])
        try receipt.validate(identity: receipt.identity)
        XCTAssertNil(receipt.memberTemplateID); XCTAssertEqual(receipt.topicID, 30)
        let scope = UUID(), target = try XCTUnwrap(ProjectEditRemoteTarget(installationReceipt: receipt, readerScope: scope))
        XCTAssertEqual(target.topicID, 30); XCTAssertEqual(target.owner, .merchant); XCTAssertEqual(target.readerScope, scope)
